import React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import List from '@mui/material/List';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemText from '@mui/material/ListItemText';

function ItemSelectionModal({ open, onClose, items, onSelectItem, title }) {

    const handleListItemClick = (item) => {
        onSelectItem(item); // Notify parent component of selection
    };

    return (
        <Dialog
            open={open}
            onClose={onClose} // Handles backdrop click & Escape key
            aria-labelledby="item-selection-dialog-title"
        >
            <DialogTitle id="item-selection-dialog-title">{title ?? 'Select an Item'}</DialogTitle>
            <DialogContent>
                <List dense>
                    {items.map((item) => (
                        <ListItemButton key={item} onClick={() => handleListItemClick(item)}>
                            <ListItemText primary={item} />
                        </ListItemButton>
                    ))}
                </List>
            </DialogContent>
            <DialogActions>
                {/* Cancel button also uses the onClose handler provided by the parent */}
                <Button onClick={onClose}>Cancel</Button>
            </DialogActions>
        </Dialog>
    );
}

export default ItemSelectionModal;