var postMessageToApp;		// will be injected with "init()"

var appLoadTime;
var util;
var bridgeReady, prmsBridgeReady, prmsBridgeReadyResolve;

// a timer to allow debug message within 30s of appstart to be accumulated and send to App for debugging
var before30s = true;
export const initDebug = (_postMessageToApp, _util) => {
    postMessageToApp = _postMessageToApp;
    util = _util;
    appLoadTime = new Date().getTime();

    // create a new promise
    prmsBridgeReady = new Promise((resolve,reject) => {
        prmsBridgeReadyResolve = resolve;
    });

    setTimeout(() => {
        before30s = false;
    }, 30000);
}

export const setBridgeReady = _bridgeReady => {
    bridgeReady = _bridgeReady;
    if (_bridgeReady) prmsBridgeReadyResolve();
}

export function getDateTimeStr(dt = new Date()) {
    const pad = (num) => num.toString().padStart(2, '0');

    const year = dt.getFullYear();
    const month = pad(dt.getMonth() + 1); // Months are zero-based
    const day = pad(dt.getDate());
    const hours = pad(dt.getHours());
    const minutes = pad(dt.getMinutes());
    const seconds = pad(dt.getSeconds());

    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}


export const createDebug = (namespace) => {
    let debug;

    // check cached versions first
    if ( ! (debug = createDebug.instances[namespace]) ) {
        debug = (...args) => {
            debug.cntr++;
            args.unshift( getDateTimeStr() + ' - ');

            // skip if not enabled
            if (!debug.enabled) return;
            if (debug.debugger){
                debugger
            }

            // timestamp
            let timestamp = new Date().getTime() - appLoadTime;

            // local console
            if (console) console.log(timestamp + " " + namespace + " " + JSON.stringify(args) );

            if (util.rjsid && !bridgeReady){
                // send debug message to rjsConsole
                util.remote.log.apply(null, args);
            } else {
                // accumulate debug msg ( < 30s after start) and send to App when bridge is ready
                if (before30s) {
                    prmsBridgeReady.then(() => {
                        postMessageToApp({
                            debug: {
                                show: {timestamp, name: namespace, args}
                            }
                        });
                    });
                } else {
                    if (bridgeReady) {
                        postMessageToApp({
                            debug: {
                                show: {timestamp, name: namespace, args}
                            }
                        });
                    }
                }
            }
        };

        if (!createDebug.instances) createDebug.instances = [];
        createDebug.instances.push(debug);
        createDebug.instances[namespace] = debug;
        debug.namespace = namespace;
        debug.cntr = 0;
        debug.enabled = true;
        debug.debugger = false;
        debug.extend = function (namespace, delimiter) {
            var subns = this.namespace + (typeof delimiter === 'undefined' ? ':' : delimiter) + namespace;
            var newDebug = createDebug.instances[subns];
            if ( !newDebug ){
                newDebug = createDebug(subns);
                newDebug.enabled = this.enabled;
                newDebug.debugger = this.debugger;
            }

            if (newDebug.debugger){
                debugger
            }
            return newDebug;
        }
    }

    return debug;
};

createDebug.instances = [];			// instances are stored in both array and keyed by their "namespace"


function extend(namespace, delimiter) {
    var subns = this.namespace + (typeof delimiter === 'undefined' ? ':' : delimiter) + namespace;
    var newDebug = createDebug.instances[subns];
    if ( !newDebug ){
        newDebug = createDebug(subns);
        newDebug.enabled = this.enabled;
        newDebug.debugger = this.debugger;
    }

    if (newDebug.debugger){
        debugger
    }
    return newDebug;
}

// if status is string, only matching namespaces will be displayed
function _showInstances(status){
    let result =[];

    if (typeof status === 'string'){
        for(let i=0; i<createDebug.instances.length; i++){
            let instance = createDebug.instances[i];

            if (instance.namespace.indexOf(status) >= 0){
                result.push(
                    instance.namespace + " - " + instance.cntr + " - " + instance.enabled + (instance.debugger ? " - debugger" : '')
                );
            }
        }
    } else {
        for(let i=0; i<createDebug.instances.length; i++){
            let instance = createDebug.instances[i];

            if (status == null || status == instance.enabled){
                result.push(
                    instance.namespace + " - " + instance.cntr + " - " + instance.enabled + (instance.debugger ? " - debugger" : '')
                );
            }
        }
    }
    result.sort((a,b) => a < b ? -1 : 1);

    return result;
}

// temporarily enable specified instances (for this session only)
// if bStop = true => enable, false => disable;       note: if both bStop & bExclusive is null, true => enable
// if bExclusive = true, disable all other instances
//
// if namespace does not start with ":", we assume top level namespaces,  (all sublevel instances will be changed accordingly)
// if namespace start with ":", we assume only lower level namespaces
// if namespaces = '*' = all
function _debugger(namespaces, bStop, bExclusive) {
    // temporarily disable specified instances (for this session only)
    let i, j;
    const split = (typeof namespaces === 'string' ? namespaces : '').split(/[,]+/);
    const len = split.length;

    // enable debugger if both bStop, bExclusive is null
    if (bStop == null && bExclusive == null){
        bStop = true;
    }

    // disable all others for <bExclusive>
    if (bExclusive){
        for(i=0; i<createDebug.instances.length; i++){
            let instance = createDebug.instances[i];
            instance.debugger = !bStop;
        }
    }

    // add specified namespaces to "createDebug.skips[]"
    for (i = 0; i < len; i++) {
        if (!split[i]) {
            // ignore empty strings
            continue;
        }

        for(j=0; j<createDebug.instances.length; j++){
            let instance = createDebug.instances[j];
            let _namespace = instance.namespace;

            if ( split[i] == '*'
                || _namespace == split[i] 							// match whole
                || _namespace.indexOf(split[i] + ":") == 0	 		// match top level namespace
                || _namespace.indexOf(":" + split[i] + ":") >= 0 	// match middle level namespace
                || _namespace.endsWith(":" + split[i]) ){			// match lowest level namespace
                instance.debugger = bStop;
            }
        }
        //let instance = createDebug.instances[ split[i] ];
        //if (instance) instance.enabled = true;
    }
}


// temporarily enable specified instances (for this session only)
// if bExclusive = true, disable all other instances
//
// if namespace does not start with ":", we assume top level namespaces,  (all sublevel instances will be changed accordingly)
// if namespace start with ":", we assume only lower level namespaces
function _enable(namespaces, bExclusive) {
    // temporarily disable specified instances (for this session only)
    let i, j;
    const split = (typeof namespaces === 'string' ? namespaces : '').split(/[,]+/);
    const len = split.length;

    // disable all others for <bExclusive>
    if (bExclusive){
        for(i=0; i<createDebug.instances.length; i++){
            let instance = createDebug.instances[i];
            instance.enabled = false;
        }
    }

    // add specified namespaces to "createDebug.skips[]"
    for (i = 0; i < len; i++) {
        if (!split[i]) {
            // ignore empty strings
            continue;
        }

        for(j=0; j<createDebug.instances.length; j++){
            let instance = createDebug.instances[j];
            let _namespace = instance.namespace;

            if (split[i] == '*'
                || _namespace == split[i] 							// match whole
                || _namespace.indexOf(split[i] + ":") == 0	 		// match top level namespace
                || _namespace.indexOf(":" + split[i] + ":") >= 0 	// match middle level namespace
                || _namespace.endsWith(":" + split[i]) ){			// match lowest level namespace
                instance.enabled = true;
            }
        }
        //let instance = createDebug.instances[ split[i] ];
        //if (instance) instance.enabled = true;
    }
}


// temporarily disable specified instances (for this session only)
// if bExclusive = true, eanble all other instances
function _disable(namespaces, bExclusive) {
    let i, j;
    const split = (typeof namespaces === 'string' ? namespaces : '').split(/[,]+/);
    const len = split.length;

    // disable all others for <bExclusive>
    if (bExclusive){
        for(i=0; i<util.createDebug.instances.length; i++){
            let instance = util.createDebug.instances[i];
            instance.enabled = true;
        }
    }

    // add specified namespaces to "createDebug.skips[]"
    for (i = 0; i < len; i++) {
        if (!split[i]) {
            // ignore empty strings
            continue;
        }

        for(j=0; j<createDebug.instances.length; j++){
            let instance = createDebug.instances[j];
            let _namespace = instance.namespace;

            if (split[i] == '*'
                || _namespace == split[i] 							// match whole
                || _namespace.indexOf(split[i] + ":") == 0 			// match top level namespace
                || _namespace.indexOf(":" + split[i] + ":") >= 0 	// match middle level namespace
                || _namespace.endsWith(":" + split[i]) ){			// match lowest level namespace
                instance.enabled = false;
            }
        }
        //let instance = createDebug.instances[ split[i] ];
        //if (instance) instance.enabled = false;
    }
}


// attach functions
createDebug._enable = _enable;
createDebug._disable = _disable;
createDebug._debugger = _debugger;
createDebug._showInstances = _showInstances;

