import React, {useState, useEffect, useRef, useCallback} from "react";
import chatIconUrlFromFile from '../images/scribbly_chat_icon.png';

import ItemSelectionModal from './ItemSelectionModal';

import {
    connectWebSocket,
    disconnectWebSocket,

    sendMessage,
    setOnMessageCallback,

    getWebSocketState,
    WebSocketStates,

    getForCompIndex,
    setForCompIndex,
    onForCompIndexChange,
} from '../websocket.js';

import { util, createDebug} from '../chatbridge';
const namespace = "(miniAppApi/components/RemoteImageInput)"
const debug = createDebug(namespace), dbg = debug;

var numOfCompInstances = 0;
var compInstanceIndixes = [];

function RemoteImageInput({ handleFileUpload, index, fromApp }) {
    util.debugFns[namespace] = function(script){ eval(script); };          // to support "util.chatbridge.debugWeb('(App.jsx)', function(){....})" on rjs Console
    console.log( "chatIconUrlFromFile = ", chatIconUrlFromFile);

    // States and handles for ItemSelectionModal
    const [isItemSelectionModalOpen, setIsItemSelectionModalOpen] = useState(false);
    const [selectedItem, setSelectedItem] = useState(null);
    const selectedItemRef = useRef(null);
    useEffect(() => {
        selectedItemRef.current = selectedItem;
    }, [selectedItem])
    const [itemsForSelectionModal, setItemsForSelectionModal] = useState(['android - S24', 'web - web2023', 'ios - ihpone 16']);
    // const handleOpenItemSelectionModal = useCallback(() => {
    //     setIsItemSelectionModalOpen(true);
    // });
    const handleCloseItemSelectionModal = useCallback(() => {
        // This will be passed as the 'onClose' prop to ItemSelectionModal
        if (selectedItemRef.current == null){
            disconnectWebSocket();
        }
        setIsItemSelectionModalOpen(false);
    });
    const handleItemSelect = useCallback((item) => {
        // This will be passed as the 'onSelectItem' prop to ItemSelectionModal
        setSelectedItem(item);
        selectedItemRef.current = item;
        console.log("Selected:", item);
        let pos = item.indexOf(' - ');
        let resource = item.substring(pos + 3);

        sendMessage("reqRemoteUI:" + JSON.stringify({
            reqId: util.uuid(),
            page: 'CameraGallery',
            resource,
            fromApp,
            params: {}
        }));

        handleCloseItemSelectionModal(); // Close selection modal after selecting
    });

    // State for chat button background color
    const [isChatActive, setIsChatActive] = useState(false); // Default to inactive (transparent)
    const defaultBgColor = "transparent";
    const activeBgColor = "lime";

    // State for WebSocket connection status
    const [wsStatus, setWsStatus] = useState(getWebSocketState());
    const updateWsStatus = () => {
        setWsStatus(getWebSocketState());
    };

    const onMessage = useCallback((data) => {
        try {
            debug("receive websocket message - data=", data);

            // sessionConfirm:ok
            if (data === 'sessionConfirm:ok') {
                sendMessage("getAppInstances:");
            } else if (data.startsWith('sessionError:')) {
                let err = data.substring('sessionError:'.length);
                alert('Error in connecting to scribblyChat server - ' + err);

                // close it if server haven't closed it in 500ms
                setTimeout(() => {
                    if (getForCompIndex() != null) {
                        try {
                            disconnectWebSocket();
                        } catch (ex) {
                            debug("Error disconnecting remoteUI websocket - ex=", ex)
                        }
                    }
                }, 500);
            } else if (data.startsWith('appInstances:')) {
                // show app instances for user to choose
                let appInstances = data.substring('appInstances:'.length);
                appInstances = JSON.parse(appInstances);

                if (appInstances.length === 0){
                    alert('Please login to scribblyChat app on your device and click this button again');
                    disconnectWebSocket();
                } else if (appInstances.length > 0){
                    // display a list for user to choose [{resource, platformOs}, ...]
                    let applist = appInstances.map(inst => inst.platformOS + ' - ' + inst.resource);
                    setItemsForSelectionModal(applist);
                    setSelectedItem(null);
                    setIsItemSelectionModalOpen(true);


                    //open={isItemSelectionModalOpen}
                    //onClose={handleCloseItemSelectionModal}
                    //items={itemsForSelectionModal}
                    //onSelectItem={handleItemSelect}


                    // one user choose one, send "reqRemoteUI" message to app
                } else {
                    alert('Developer error - invalid app instances');
                    disconnectWebSocket();
                }
            } else if (data.startsWith('respRemoteUI:')) {
                let resp = data.substring(13);
                let {reqId, ok, error, close, result} = JSON.parse(resp);

                if (ok){
                    // do nothing
                } else if (error){
                    alert("RemoteUI req error - " + error);
                    disconnectWebSocket();
                } else if (close){
                    disconnectWebSocket();
                } else if (result && result.blob){
                    handleFileUpload(index, result.blob);
                } else {
                    alert('Invalid respRemoteUI command');
                }
            }
        } catch(ex){
            debug("remoteUI weboscket onMessage -ex=", ex);
        }
    });
    const onWebsocketOpen = useCallback(() => {
        debug('WebSocket opened');
        setForCompIndex(index);
        updateWsStatus();
        // Send an initial message or user identification
        sendMessage("sid," + util.getCookie('scribblyChat-session') + ",mod,remoteUI");
    });
    const onWebsocketClose = useCallback(() => {
        debug('WebSocket closed');
        updateWsStatus();
        setForCompIndex(null);
    });
    const onWebsocketError = useCallback((error) => {
        debug('WebSocket error:', error);
        updateWsStatus(); // Update to CLOSED or reflect error
        alert(`Failed to connect to chat because of connect error. Please open it again later.`);

        disconnectWebSocket();
    });

    // component onload / offload
    useEffect(() => {
        numOfCompInstances++;
        compInstanceIndixes.push(index);

        let unsubForCompIndexChange = onForCompIndexChange(() => {
            if (getForCompIndex() === index){
                // hook up websocket with this component instance
                setOnMessageCallback(onMessage);
                setIsChatActive(true);
            } else {
                setIsChatActive(false)
            }
        });

        // take existing websocket by default
        if ( getForCompIndex() != null){
            setForCompIndex(index);
        }

        return () => {
            unsubForCompIndexChange();

            // keep track of <index>
            numOfCompInstances--;
            let pos = compInstanceIndixes.indexOf(index);
            if (pos >= 0){
                compInstanceIndixes.splice(pos, 1);
            }

            // close/reassign websocket
            if (!numOfCompInstances){
                disconnectWebSocket()
            } else {
                if ( getForCompIndex() === index){
                    if (pos >= 0 && compInstanceIndixes.length >= pos + 1){
                        setForCompIndex( compInstanceIndixes[pos] );
                    } else {
                        setForCompIndex( compInstanceIndixes[compInstanceIndixes.length - 1] );
                    }
                }
            }
        }
    }, []);


    const handleChatConnectionToggle = () => {
        if (wsStatus === WebSocketStates.CONNECTING || wsStatus === WebSocketStates.CLOSING) {
            alert("WebSocket is currently connecting or closing. Please wait.");
            return;
        }

        if (getForCompIndex() == null){
            // Current state is inactive and WS is closed: Try to connect
            debug(`Attempting to connect chat for item ${index}`);
            setWsStatus(WebSocketStates.CONNECTING); // Manually set to connecting immediately for UI feedback

            // open websocket & associate
            connectWebSocket(
                onWebsocketOpen,
                onWebsocketClose,
                onWebsocketError
            );
        } else if ( getForCompIndex() === index){
            // close websocket
            disconnectWebSocket();
        } else {
            // websocket open but not for this component
            setForCompIndex( index );
        }
    };


    return (
        <div
            style={{
                border: "2px dashed #ccc", // dragging ? "2px dashed #007bff" : "2px dashed #ccc",
                padding: "20px",
                borderRadius: "5px",
                textAlign: "center",
                backgroundColor: "#fff",  // dragging ? "#e9f5ff" : "#fff",
                position: "relative",
            }}
        >
            {/* Chat Icon Button with PNG image */}
            <button
                onClick={handleChatConnectionToggle}
                disabled={wsStatus === WebSocketStates.CONNECTING || wsStatus === WebSocketStates.CLOSING}
                style={{
                    position: "absolute",
                    bottom: "2px",
                    right: "2px",
                    //background: "#007bff", // You might want to make this transparent or match your icon
                    //background: isChatActive ? activeBgColor : defaultBgColor,
                    background: isChatActive ? activeBgColor : defaultBgColor,
                    border: isChatActive ? "2px solid darkgreen" : "none",
                    borderRadius: "50%",
                    width: "28px",
                    height: "28px",
                    padding: "0", // Remove padding if the image itself has whitespace
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    cursor: "pointer",
                    boxShadow: "0px 2px 5px rgba(0,0,0,0.2)",
                    overflow: "hidden" // Ensures the image doesn't spill out if it's not perfectly circular/square
                }}
                aria-label={isChatActive ? "chat connected" : "chat closed"}
            >
                <img
                    src={chatIconUrlFromFile} // Use the variable for the icon path
                    alt="Chat"
                    style={{
                        width: "24px",  // Adjust size of the image inside the button
                        height: "24px", // Adjust size of the image inside the button
                        // objectFit: "contain" // Optional: if your image has different aspect ratio
                    }}
                />
            </button>

            <ItemSelectionModal
                open={isItemSelectionModalOpen}
                onClose={handleCloseItemSelectionModal}
                items={itemsForSelectionModal}
                onSelectItem={handleItemSelect}
                title='Please choose ScribblyChat instance to connect'
            />
        </div>
    );
}

export default RemoteImageInput;
