export function getOSAndDevice() {
    const ua = navigator.userAgent;
    let os = "UnknownOS";
    let device = "UnknownDevice";

    // Detect OS
    if (/Windows NT 10.0|Windows 10.0|Windows NT 6.3|Windows 8.1/.test(ua)) {
        os = "Windows";
    } else if (/Windows NT 6.1|Windows 7/.test(ua)) {
        os = "Windows";
    } else if (/Mac OS X/.test(ua)) {
        os = "macOS";
    } else if (/Android/.test(ua)) {
        os = "Android";
    } else if (/iOS|iPhone|iPad|iPod/.test(ua)) {
        os = "iOS";
    } else if (/Linux/.test(ua)) {
        os = "Linux";
    }

    // Detect Device
    if (/Android/.test(ua) && !/Mobile/.test(ua)) {
        device = "AndroidTablet";
    } else if (/iPad/.test(ua)) {
        device = "iPad";
    } else if (/iPhone/.test(ua)) {
        device = "iPhone";
    } else if (/Android/.test(ua)) {
        device = "AndroidPhone";
    } else if (/Macintosh/.test(ua) && /Mac OS X/.test(ua)) {
        device = "Mac";
    } else if (/Windows/.test(ua) || /Linux/.test(ua)) {
        device = "Desktop";
    }

    //return `OS: ${os}, Device: ${device}`;
    return `${os}_${device}`;
}

