function getTimeStr(){
	var dt = new Date();
	return dt.getHours() + ':' +dt.getMinutes() + ':' + dt.getSeconds() + '.' + dt.getMilliseconds();
}

// 1. create iframe pointing to script on jsconsole.com domain
// 2. create console object with: log, dir, etc?
// 3. console.log runs postMessage with json.stringified content
// 4. jsconsole.com/remote/?id.onMessage = send to server, and wait for response. 
function sortci(a, b) {
  return a.toLowerCase() < b.toLowerCase() ? -1 : 1;
}

function instack(o, stack){
  if( !stack ) return false;
  for(var i=0,len=stack.length; i<len; i++){
    if( o === stack[i] ) return true;
  }
}

function indent(stack, parts, closing){
    var r, s = '', len = stack ? stack.length : 0;
    while(len-->0) s += '    ';
    if( !parts ) r = s;
    else r = '\n' + s + '  ' 
	    + parts.join( '\n' + s + ', ') 
	    + '\n' + s + closing;
    return r;
}

// from console.js
function stringify(o, simple, stack, opts) { 
  if( opts ){
    var saved_opts = stringify.opts;
    stringify.opts = opts;
    var res = stringify(o, simple, stack);
    stringify.opts = saved_opts;
    return res;
  }
  
  var json = '', i, type = ({}).toString.call(o), parts = [], names = [];
  if(!stack ) stack = [];
  
  if (type == '[object String]') {
    json = '"' + o.replace(/\n/g, '\\n').replace(/"/g, '\\"') + '"';
  } else if (type == '[object Number]') {
    json = o+'';
  } else if (type == '[object Boolean]') {
    json = o ? 'true' : 'false';
  } else if (type == '[object Function]') {
    json = (stringify.opts.showFunc || stack.length<=1) ? o.toString() : '[Function]';
  } else if (o === null) {
    json = 'null';
  } else if (o === undefined) {
    json = 'undefined';
  } else if (type == '[object Array]') {
    if( instack(o,stack) ) return '[circular]';
  
    json = '[';
    if(stack.length > stringify.opts.depth) json += '...]';
    else {
	stack.push(o);
	for (i = 0; i < o.length; i++) {
	  parts.push(stringify(o[i], simple, stack));
	}
	stack.pop();
	json += indent(stack, parts, ']')
    }
  } else if (type == '[object Object]') {
    if( instack(o,stack) ) return '[circular]';
  
    json = '{';
    if(stack.length > stringify.opts.depth) json += '...}';
    else {	
	for (i in o) {
	  names.push(i);
	}
	names.sort(sortci);
	stack.push(o);
	for (i = 0; i < names.length; i++) {
	  parts.push(stringify(names[i],null,stack) + ': ' + stringify(o[names[i] ], simple, stack));
	}
	stack.pop();
	json += indent(stack, parts, '}');
    }
  } else if (simple == undefined) {
    if( instack(o,stack) ) return '[circular]';
  
    json = type + '{';
    if(stack.length > stringify.opts.depth) json += '...}\n';
    else {		
	for (i in o) {
	  names.push(i);
	}
	names.sort(sortci);
	stack.push(o);
	for (i = 0; i < names.length; i++) {
	  parts.push(names[i] + ': ' + stringify(o[names[i]], true, stack)); // safety from max stack
	}
	stack.pop();
	json += indent(stack, parts, '}');
    }
  } else {
    try {
      json = o+''; // should look like an object
    } catch (e) {}
  }
  return json;
}

stringify.opts = {
    "showFunc": false,
    "depth": 2
};

function prcsMsg(data){
  // eval the command in "data" parameter
  try {
    if( data.indexOf('rjsid=') == 0 ){
      rjsid = data.substr(6);
		
	  remote.log(getTimeStr() + " - Remote.js: prcsMsg", "parsed data from rjs server", "rjsid=" + rjsid);
	  $.util.emitChannel('rjsid', rjsid);
	  /*
      if( getQueryVar('debug') == 'yes' ) {
          document.title += " (rjsid=" + window.rjsid + ")";
      }
	  */
    } else if (data.indexOf('console.log') == 0) {
      eval('remote.echo(' + data.match(/console.log\((.*)\);?/)[1] + ', "' + data + '", true)');
    } else {
      remote.echo(eval(data), data, undefined); // must be undefined to work
    }
  } catch (e) {
    remote.error(e, data);
  }	
}

var msgType = '';
export var remote = {
  //getQueryVar: getQueryVar,
  log: function () {
	//if(console) console.log.apply(this, arguments);
	if(!debugEnabled) return;		// no-op if debug is not enabled  
    watchdog();
	
  
    //var argsObj = stringify(arguments.length == 1 ? arguments[0] : [].slice.call(arguments, 0));
    var response = [];
	
    [].forEach.call(arguments, function (args) {
      response.push(stringify(args, true));
    });
	  
    var msg = JSON.stringify({ response: response, cmd: 'remote console.log', type: msgType });
    resultQueue.push(msg);
    
    msgType = '';
  },
  info: function () {
    msgType = 'info';
    remote.log.apply(this, arguments);
  },
  echo: function () {
    var args = [].slice.call(arguments, 0),
        plain = args.pop(),
        cmd = args.pop(),
        response = args;

    var argsObj = stringify(response, plain),
        msg = JSON.stringify({ response: argsObj, cmd: cmd });
    resultQueue.push(msg);
  },
  error: function (error, cmd) {
    var msg = {response: 'unknown error', cmd: cmd, type: 'error'};
    
    if( typeof(error) == 'string' ) msg.response = error;
    else if( typeof(error) == 'object' ) msg.response = error.message ? error.message : JSON.stringify(error);

    msg = JSON.stringify(msg); 
    resultQueue.push(msg);
  }
};

