var _pageunload;
var noop = function(){};
var rjsid = null,
	rjsToken = null,
	jid = null,  // name@domain/resource,  or  random jid (for debug before login)
	debugEnabled= false,		// will be enabled by calling "rjsInitialize()"
    origin = null, rjsWnd = null, pageUrl = null,
    resultQueue = [],
    xhrInUse = false; 

function ajax(method, url, callback, timeout, retry, params, lastAjax, onOtherChange) {
    retry = (retry > 0) ? retry : 0;
    if( _pageunload && !lastAjax ) return;		// universal page unload indicator to stop any xhr work

    var xhr ,  // new XMLHttpRequest(),   
    xhrAborting,
    xhrTimer, xhrTimer1,
    xhrConnErrCntr=0;

    //xhrInUse = true;
    // if( xhr.onreadystatechange ) delete xhr.onreadystatechange;
    // xhr.onreadystatechange = null;
    try {
		xhr = new XMLHttpRequest();
		
		xhr.open( method, url, true);
		xhr.timeout = (timeout ? timeout : 7000);
		if( (method == 'POST') && params ){
			xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
			xhr.send(params);
		} else {
			xhr.send(null);
		}
		
		xhr.onreadystatechange = function() {
			var status, responseText, other;
			if ( this.readyState === 4 && !xhrAborting) {
				// xhrInUse = false;  

				// note: sometimes, "this.status" is not accessible (when aborted)
				try {
					status = this.status;
					if( typeof this.responseText === 'string' ) responseText = this.responseText;
				} catch(ex){
					if(onOtherChange) onOtherChange({error: ex});
				}

				// clean up
				try {
					delete this.onreadystatechange;
					this.onreadystatechange = null; //noop;
					delete this;
				} catch(ex){
					//alert('ajax - ex=' + JSON.stringify(ex) );
				}

				if(xhrTimer) { 
					clearTimeout(xhrTimer); 
					xhrTimer = null; 
				}
				
				callback( status == 200 ? responseText : undefined);
			} else {
				if(onOtherChange) onOtherChange({status: this.readyState});
			}
		};
	
		xhrTimer = setTimeout(function () {
			xhrTimer = undefined;
			xhrAborting = true;
			try { xhr.abort(); } catch(ex){}
			xhrAborting = false;

			// clean up
			delete xhr.onreadystatechange;
			xhr.onreadystatechange = null; //noop;
			//delete xhr;

			// xhrInUse = false;  // xhr.onreadystatechange = null;
			if( retry >0) {
				retry--;
				ajax(method, url, callback, timeout, retry, params);
			} else {		    
				callback();   // to make sure that callback() is always called
			}
		}, timeout ? timeout : 7000);

		xhrConnErrCntr = 0;	
    } catch(ex){
		// xhrInUse = false;  
		delete xhr.onreadystatechange;
		xhr.onreadystatechange = null; //noop;
		//delete xhr;

		callback(null, ++xhrConnErrCntr > 10 ? null : -2 ) 
    }
};

var getsidInProgress = false;
var getsidCallbacks = [];

function getsid(callback){
  // if in progress, save callback & return
  if( getsidInProgress ){
	  if(callback ) getsidCallbacks.push(callback);
	  return;
  }

  // if xhr busy, do it 100 ms later
  if( xhrInUse || !$.rjsServerUrl) {
      setTimeout(() => {
		  getsid(callback);
	  }, 100);
  } else {
	  // block multi-entry, also prevent dead lock in case of server errors
	  getsidInProgress = true;
	  setTimeout(() => {
		  getsidInProgress = false;	
	  }, 10000);
	  
	  // post to rjs server to get "rjsid"
	  var rjsGetidUrl = $.rjsServerUrl + '/ssjs/rjs/getid1';
	  remote.log(getTimeStr() + " - Remote.js: get rjsid", "post to rjs server", rjsGetidUrl);
	  
      ajax('POST', rjsGetidUrl, function(data){
		  try {
			  getsidInProgress = false;
			  remote.log( getTimeStr() + "- Remote.js: get rjsid", "data from rjs server", data);
			  
			  if( typeof(jid) == 'number' ){		// debug before login
				  debugEnabled = true;
				  if( data && data.indexOf(',on') >= 0 ) {
					  data = data.replace(',on', '');
				  }
			  } else {								// debug after login
				  debugEnabled = true;
				  /*
				  if( data && data.indexOf(',on') >= 0 ){
					  debugEnabled = true;
					  data = data.replace(',on', '');
				  } else {
					  debugEnabled = false;				  
				  }
				  */
			  }
			  var _msg = getTimeStr() + " - Remote.js(get rjsid) parsed data from rjs server , debugEnabled=" + debugEnabled;
			  if (debugEnabled) remote.log(_msg);
			  else console.log(_msg);

			  if(data && (parseInt(data) > 0) ) {
				  rjsid = parseInt(data);
				  if ( data.split(',').length > 1 ) rjsToken = data.split(',')[1];
				  //$.util.rjsid = rjsid;
				  
				  remote.log( getTimeStr() + " - Remote.js: get rjsid", "parsed data from rjs server", "rjsid=" + rjsid, "rjsToken=" + rjsToken);
				  $.util.emitChannel('rjsid', rjsid);

				  // DO NOT interact with server if debug is off --- for server performance !!!
				  if( debugEnabled ) {
                      $.timerLastTime = Date.now();
                      $.timer = setTimeout(exchangeData,0);
                  }				  

				  if(callback) callback();
				  if(getsidCallbacks && getsidCallbacks.length > 0 ){
					  getsidCallbacks.forEach(cb => {
						  try {
							  if(cb) cb();
						  } catch(ex){
							  remote.log( getTimeStr() + ' - Remote.js: Exception in getsidCallbacks', ex);
						  }
					  });
					  getsidCallbacks.splice(0, getsidCallbacks.length);
				  }
			  }
		  } catch(ex){
			  remote.log( getTimeStr() + ' - Remote.js: Exception in getsid', ex);
			  setTimeout(() => {
				  getsid(callback);
			  },  100);  
		  };	  
      }, null, 10, 'url=' + encodeURIComponent(pageUrl = jid) );
  }
}
$.getsid = getsid;    // for debug in console

