function processRespData(body){
    var post, posts = body.split('\n');
    while( post = posts.shift() ){
        if( post.substr(0,5) == 'data=' ) {
			post = decodeURIComponent(post.substr(5));
			//if( rjsWnd) rjsWnd.postMessage(post, origin);
			prcsMsg(post);
		} else if( post.substr(0,8) == 'expired=' ) {
			rjsid = undefined;
			setTimeout(getsid,10);
			break;
		}
    }
}

function prepareReqData(){
    var s = '', data;
    while( resultQueue.length && rjsid && (s.length < 1e4) ){
        data = resultQueue.shift();
	if( !data ) continue;
        s += 'data=' + encodeURIComponent(data) + '\n';
    }
    return s + 'end\n';
}

function ajaxCallback(data, status){
    if( data ) processRespData(data);
    if( status == -2 ){
		debugger
		if( pageUrl ) getsid();			// note: pageUrl == jid
		return;
    }
    
    // arrange next polling
    if(rjsid && !$.timer){
        $.timerLastTime = Date.now();
        $.timer = setTimeout(exchangeData, 250);
    }
}

function watchdog(){
    if(!debugEnabled) return;

    // limit queue to 1000 items
    if ( resultQueue.length > 300 ){
        resultQueue.push( stringify({ response: 'watchdog - resultQueue overflow - ' + (resultQueue.length - 300) + ' items trimmed. jid = ' + jid, type: 'info' }) );
        resultQueue.splice(0, resultQueue.length - 300);
    }

    // start rjsTimer if idle for more than 5 seconds
    if (!$.timer && Date.now() - $.timerLastTime > 5000 ){
        if (!rjsid){
            resultQueue.push( stringify({ response: 'watchdog - restart remote timer with getsid(), jid = ' + jid, type: 'info' }) );
            $.timerLastTime = Date.now();
        	getsid(function(){
        		resultQueue.push( stringify({ response: 'Connection established with ' + jid, type: 'info' }) );
        	});
        } else {
             resultQueue.push( stringify({ response: 'watchdog - restart remote timer, jid = ' + jid, type: 'info' }) );
            $.timer = setTimeout(exchangeData, 250);
            $.timerLastTime = Date.now();    
        }
    }
}

// call watchdog every 5 seconds
setInterval(() => {
    watchdog();
}, 5000);

function exchangeData(){
    $.timer = null;

    ajax('POST', $.rjsServerUrl + '/ssjs/rjs/' + rjsid + '_' + rjsToken, ajaxCallback, null, null, prepareReqData() );

    // attach master-slave election process
    //if ($.util && $.util.msTimerHandler) $.util.msTimerHandler();
}

