const stripAwarenessUser = (content) => {
    var pos1, pos11, pos12, pos2, pos21, pos22;
    var part1 = '', part2 = '', part3 = '';

    // <span class="ProseMirror-yjs-cursor-scribblychat ProseMirror-yjs-cursor ProseMirror-widget" style="border-color: #ffa500">⁠</span>
    pos1 = content.indexOf('ProseMirror-yjs-cursor-scribblychat');
    if (pos1 >= 0){
        pos11 = content.lastIndexOf('<span ', pos1);
        pos12 = content.indexOf('</span>', pos1);

        // <div class="ProseMirror-yjs-cursor-scribblychat" style="background-color: #ffa500">skang (web1)</div>
        pos2 = content.indexOf('ProseMirror-yjs-cursor-scribblychat', pos1 + 35);
        if (pos2 >= 0){
            pos21 = content.lastIndexOf('<div ', pos2);
            pos22 = content.indexOf('</div>', pos2);
        }

        // span  ... div
        if (pos11 >= 0 && pos12 >= 0){
            if (pos21 >=0 && pos22 >=0){
                if (pos12 < pos21){
                    // span ... div
                    part1 = content.substring(0, pos11);
                    if (pos12 + 7 < pos21) part2 = content.substring(pos12 + 7, pos21);
                    part3 = content.substring(pos22 + 6);
                } else {
                    // div ... span
                    part1 = content.substring(0, pos21);
                    if (pos22 + 6 < pos11) part2 = content.substring(pos22 + 6, pos11);
                    part3 = content.substring(pos12 + 7);
                }
            } else {
                // span only
                part1 = content.substring(0, pos11);
                part3 = content.substring(pos12 + 7);
            }

            if (part2.length > 0) {
                return [part1, part2, part3].join('');
            } else {
                return [part1, part3].join('');
            }
        } else if (pos21 >=0 && pos22 >=0){
            // div only
            part1 = content.substring(0, pos21);
            part3 = content.substring(pos22 + 6);
            return [part1, part3].join('');
        }

    }

    return content;
};

const createDiff1 = (oldVal, newVal) => {
    try {
        let n1=0, n3 = oldVal.length, n2=n3-1;
        let m1=0, m3 = newVal.length, m2=m3-1;

        // compare forward to find n1, m1
        while(n1 < n3 && m1 < m3 && oldVal[n1] === newVal[m1]){
            n1++;
            m1++;
        }

        // compare backward to find n2, m2
        if (n2 >= 0 && m2 >= 0){
            while(n2 >= n1 && m2 >= m1 && oldVal[n2] === newVal[m2]){
                n2--;
                m2--;
            }
        }

        //debug("oldVal=", oldVal);
        //debug("newVal=", newVal);

        //debug("n1,n2,n3=", n1,n2,n3);
        if (n1 < n3) debug("oldVal[n1-n2]=", oldVal.substring(n1,n2+1));

        //debug("m1,m2,m3=", m1,m2,m3);
        if (m1 < m3) debug("newVal[m1-m2]=", newVal.substring(m1,m2+1))

        //let newVal1 = oldVal.substr(0,n1) + newVal.substring(m1,m2+1) + oldVal.substr(n2+1);
        //debug("newVal1=", newVal1);

        //debug("comparison=", newVal1 == newVal);

        let diff = [];

        // copy the first section in original
        if (n1 > 0) 	diff.push([0,n1]);

        // delete the second section in original
        if (n1 <= n2)	diff.push([-1, n2-n1+1]);
        //if (n1 < n3) 	diff.push([-1,n2-n1+1]);

        // add the second section in new value
        if (m1 <= m2) 	diff.push([1, newVal.substring(m1,m2+1)]);

        // copy the third section in original
        if (n2 < n3-1) 	diff.push([0,n3-n2-1]);
        return diff;
    } catch(ex){
        debug("createDiff1 - ex", ex);
    }
};

