// msg = {<action>: {....}}, where an action response is expected
//     action: 'saveBlob' | 'getBlobContent' | 'createNewNote' | 'reqAppNavigate'
// callback(err, res)
// timeout: 2000ms by default
var callbackNum = 0;
const callbackActions = ['saveBlob', 'getBlobContent', 'createNewNote', 'reqAppNavigate'];
const getActionFromData = (data) => {
    for (let action of callbackActions){
        if ( data[action]){
            return action;
        }
    }
}

// send data back to <postMessageToAppCB>
export const emitResDataFromApp = data => {
    let action, resData;
    for (action of callbackActions){
        if (resData = data[action + 'Res']){
            util.emit(action + 'Res', resData);
            return true;
        }
    }
}

const postMessageToAppCB = (msg, callback, timeout) => {
	let fn, timer, action, cbNum = ++callbackNum;
	if (!timeout) timeout = TIMEOUT;

	msg.cbNum = cbNum;		// identify <msg> with <cbNum>
    if (action = getActionFromData(msg)){
        timer = setTimeout(() => {
            timer = null;
            util.off(action + 'Res', fn);

            callback('Timeout');
        }, timeout);

        util.on(action + 'Res', fn = ({cbNum: _cbNum, err, res}) => {
            if (cbNum !== _cbNum) return;

            // response for matched msg
            if (timer) clearTimeout(timer);
            util.off(action + 'Res', fn);
            callback(err, res);
        });

        postMessageToApp(msg);
    }
};

// timeout: default 2000ms
const prmsPostMessageToAppCB = (msg, timeout) => {
	return new Promise((resolve, reject) => {
		postMessageToAppCB(msg, (err, res) => {
			if (err) {
				reject(err);
			}
			else {
				resolve(res);
			}
		}, timeout)
	})
};

// scribblyChat bridge for web ===== begin
const postMessageToApp = (msg, wndOrChannel) => {
    // default to use "bridgeChannel" if not supplied
    if (wndOrChannel === undefined && bridgeChannel.wnd){
        wndOrChannel = bridgeChannel;
    }

    window.tmpWnd = wndOrChannel;
    if (!wndOrChannel){
        // buffer changes before "whiteboard" initial "sync"
        if (beforeYjsSync && msg.yChanges ){
            yChangesBufferBeforeSync.push(msg.yChanges);
            return;
        }

        msg = JSON.stringify(msg);		// always

        if (typeof window !== 'undefined' && window.ReactNativeWebView){
            // react-native-webview
            window.ReactNativeWebView.postMessage( msg  );
        } else if (typeof window !== 'undefined' && window.parent?.postMessage) {
            // iframe
            window.parent.postMessage(msg, '*');
        } else {
            throw "not hosted in scribblyChat";
        }
    } else if (wndOrChannel.sidweb && wndOrChannel.sidapp && wndOrChannel.wnd){
        // post msg to channel

        msg = {
            sidweb: wndOrChannel.sidweb,
            sidapp: wndOrChannel.sidapp,
            data: msg
        };

        msg = JSON.stringify(msg);		// always

        if (typeof window !== 'undefined' && window.ReactNativeWebView){
            // react-native-webview
            window.ReactNativeWebView.postMessage( msg );
        } else if ( wndOrChannel.wnd.postMessage) {
            // iframe
            wndOrChannel.wnd.postMessage(msg, '*');
        } else {
            throw "postMessageToApp - unexpected error";
        }

    } else {
        // post msg to wnd

        let wnd = wndOrChannel;
        msg = JSON.stringify(msg);		// always

        if (typeof window !== 'undefined' && window.ReactNativeWebView){
            // react-native-webview
            window.ReactNativeWebView.postMessage( msg  );
        } else if ( wnd.postMessage) {
            // iframe
            wnd.postMessage(msg, '*');
        } else {
            throw "postMessageToApp - unexpected error";
        }
    }
};

