const b64toBlob = (b64Data, contentType='', sliceSize=512) => {
    const byteCharacters = atob(b64Data);
    const byteArrays = [];

    for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
        const slice = byteCharacters.slice(offset, offset + sliceSize);

        const byteNumbers = new Array(slice.length);
        for (let i = 0; i < slice.length; i++) {
            byteNumbers[i] = slice.charCodeAt(i);
        }

        const byteArray = new Uint8Array(byteNumbers);
        byteArrays.push(byteArray);
    }

    const blob = new Blob(byteArrays, {type: contentType});
    return blob;
}

// postMessageToAppCB(err, res)
//		note: content is the base64Url of sth like image (jpeg/png), sound, movie ...
const createBlob = ({content, type, blobhrefApp}, postMessageToAppCB) => {
    try {
        let pos = content.substring(0, 100).indexOf(';base64,');
        if (content.substring(0,5) != 'data:' || pos < 0){
            if (postMessageToAppCB) {
                postMessageToAppCB("Error - invalid data, expect base64URL format");
            }
            return;
        }

        let b64Data = content.substring(pos+8);
        if (!type) type = content.substring(5, pos);
        const blob = b64toBlob(b64Data, type);

        //let blob = new Blob([content], {type});
        let bloburl = URL.createObjectURL(blob);

		if (postMessageToAppCB) {
			postMessageToAppCB(null, bloburl);
		}

        return bloburl;
    } catch(ex){
        console.log("createBlob - ex=", ex);
		if (postMessageToAppCB){
			postMessageToAppCB(ex);
		}
    }
};

