const validateBlobMaps = async (blobmaps, postMessageToAppCB, cbChangeContent) => {
    let validBlobmaps = [], invalidBlobmaps = blobmaps;		// start with assumption of all invalid
    let i, res, len = invalidBlobmaps.length;

    try {
        debug("validateBlobMaps - before - validBlobmaps, invalidBlobmaps=", validBlobmaps, invalidBlobmaps);

        for (i=len-1; i>= 0; i--){
            try {
                let o = invalidBlobmaps[i];
                res = await prmsExtractBlobContent(o.blobhref, null, true);
                debug("validateBlobMaps - blobhref, res=", o.blobhref, res);

                if (res.type){
                    invalidBlobmaps.splice(i,1);
                    validBlobmaps.push(o);

					blobMapFwd[o.blobhref] = o.blobhrefApp;
					blobMapRev[o.blobhrefApp] = o.blobhref;
				}
            } catch(ex1){
                debug("validateBlobMaps - ex1=", ex1);
            }
        }

        debug("validateBlobMaps - after - validBlobmaps, invalidBlobmaps=", validBlobmaps, invalidBlobmaps);

		if (cbChangeContent) cbChangeContent(validBlobmaps);
		if (postMessageToAppCB) postMessageToAppCB(null, invalidBlobmaps);
	} catch(ex){
		if (cbChangeContent) cbChangeContent(validBlobmaps);
		if (postMessageToAppCB) postMessageToAppCB(null, invalidBlobmaps)
        debug("validateBlobMaps - ex=", ex);
    }
};

