// return [blobhref, pos, isBlobhrefApp]
const findNextBlobhref = (content, pos) => {
	let pos1, pos2, matched, hrefstr, blobhref, isBlobhrefApp;

	if (!pos) pos = 0;
	matched = content.slice(pos).match(/(href|src)=['"](blob:[^'"]+)['"]/);
	if (matched && matched.length == 3){
		hrefstr = matched[0];
		blobhref = matched[2];
		isBlobhrefApp = blobhref.indexOf('blob:scribblychat_') === 0;

		if (matched[1] == 'href') {
			pos = pos + 6 + content.slice(pos).indexOf(hrefstr);
		} else {
			pos = pos + 5 + content.slice(pos).indexOf(hrefstr);
		}
	}
	return [blobhref, pos, isBlobhrefApp];
};

// replace blobhrefApp => blobhref in window.document
const renderBlobInDocument = (blobhrefApp, blobhref) => {
	// Query all elements that have the href attribute equal to currentHrefValue
	const elements = window.document.querySelectorAll(`[href="${blobhrefApp}"]`);

	// Iterate over the NodeList of elements found
	elements.forEach(element => {
		// Set the new href attribute value
		element.href = blobhref;
	});
};

const renderBlobsInContent = (content) => {
	return new Promise( async (resolve, reject) => {
		try {
			var blobhref, blobhrefApp, isBlobhrefApp, blobContent, res, pos = 0;

			do {
				// find next blobhref or blobhrefApp
				[blobhrefApp, pos, isBlobhrefApp] = findNextBlobhref(content, pos);
				if (!blobhrefApp) break;
				if (!isBlobhrefApp) continue;

				if ( !(blobhref = blobMapRev[blobhrefApp]) ){
					res = await prmsPostMessageToAppCB({getBlobContent: {blobhrefApp}});
					// res = {content, type, blobhrefApp}

					blobhref = createBlob(res);
					postMessageToApp({createdBlob: {blobhref, blobhrefApp}});
					// send res to App and ignore

					// replace blobhref => blobhrefApp
					blobMapFwd[blobhref] = blobhrefApp;
					blobMapRev[blobhrefApp] = blobhref;
				}

				// replace blobhrefApp => blobhref (for rendering in Browser)
				content = content.substring(0,pos) + blobhref + content.substring(pos + blobhrefApp.length);

				// replace blobhrefApp => blobhref in window.document
				renderBlobInDocument(blobhrefApp, blobhref);
			} while (blobhrefApp);

			resolve(content);
		} catch(ex){
			reject(ex)
		}
	})
};

