// replace blobhref => blobhrefApp before saving to App
const replaceBlobsInContent = (content) => {
	return new Promise(async (resolve,reject) => {
		try {
			var blobhref, blobhrefApp, isBlobhrefApp, blobContent, res, pos = 0;

			do {
				// find next blobhref or blobhrefApp
				[blobhref, pos, isBlobhrefApp] = findNextBlobhref(content, pos);
				if (!blobhref) break;
				if (isBlobhrefApp) continue;

				if ( !(blobhrefApp = blobMapFwd[blobhref]) ){
					try {
						// extract blobcontent => app DB
						blobContent = await prmsExtractBlobContent(blobhref);

						// save blobContent to App => blobhrefApp
						res = await prmsPostMessageToAppCB({saveBlob: {blobContent, blobhref}});

						// add map blobhref <=> blobhrefApp
						blobMapFwd[res.blobhref] = blobhrefApp = res.blobhrefApp;
						blobMapRev[res.blobhrefApp] = res.blobhref;
					} catch(ex1){
						// skip this one & continue
						debug("failed to find content of blobhref - " + blobhref);

						pos += blobhref.length;
						continue;
					}
				}

				// replace blobhref => blobhrefApp (for saving to DB)
				content = content.substring(0,pos) + blobhrefApp + content.substring(pos + blobhref.length);
			} while (blobhref);

			resolve(content);
		} catch(ex){
			reject(ex);
		}
	})
};

