    // store N click time (<500ms) in util.state.pressTime  -- record last time a button is clicked,  "namespace" => {lastTime, n}
    nClickHandler(callback, namespace="default", N=7){
        return () => {
            if (!namespace) namespace = 'default';
            let now = new Date().getTime();
            let pressTime = util.state.pressTime[namespace] ?? {};

            // reset if last time if too long ago or does not exist
            if (pressTime.lastTime + 500 < now || !pressTime.lastTime ){
                pressTime = {lastTime: now, n: 1};
            } else {
                pressTime.n++;
                pressTime.lastTime = now;
            }
            util.state.pressTime[namespace]  = pressTime;

            if (pressTime.n >= N){
                // clear history
                util.state.pressTime[namespace] = null;

                // trigger handler if click N times already
                callback();
            }
        }
    }


    clearCookie(cookieName) {
        if (typeof document === 'undefined') return;

        // The expires attribute is set to a date in the past, which causes the browser to delete the cookie.
        document.cookie = cookieName + "=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/";
    }

    setCookie(cookieName, cookieValue, daysToExpire = undefined, isSecure = true) {
        if (typeof document === 'undefined') return null;

        var expires = "";
        if (daysToExpire !== undefined) {
            var date = new Date();
            date.setTime(date.getTime() + (daysToExpire * 24 * 60 * 60 * 1000));
            expires = "expires=" + date.toUTCString();
        }
        var secureFlag = isSecure ? ";secure" : "";
        document.cookie = cookieName + "=" + cookieValue + ";" + expires + ";path=/" + secureFlag;
    }

    // default session cookie: "scribblyChat-session"
    getCookie(name) {
        try {
            if (typeof document === 'undefined') return null;

            // Split cookie string and get all individual name=value pairs in an array
            var cookieArr = document.cookie.split(";");

            // Loop through the array elements
            for (var i = 0; i < cookieArr.length; i++) {
                var cookiePair = cookieArr[i].trim();
                // Check if the name is correct
                if (cookiePair.startsWith(name + "=")) {
                    // Decode the cookie value and return
                    return decodeURIComponent(cookiePair.substring(name.length + 1));
                }
            }

            // Return null if not found
            return null;
        } catch(ex){
            debug("getCookie - ex=", ex);
            return null;
        }
    }


    // type: date, datetime, decimal string, number, boolean
    isSameValue(a, b, type){
        try {
            if (!a && !b) return true;
            if (!a && b || a && !b) return false;

            if (type === 'date' || type === 'day') {
                // compare day only
                return moment(a).format('M/DD/YYYY') === moment(b).format('M/DD/YYYY');
            } else if (type === 'datetime' || type === 'minute') {
                // compare to minute
                return moment(a).format('M/DD/YYYY hh:mm') === moment(b).format('M/DD/YYYY HH:mm');
            } else if (type === 'second') {
                // compare to second
                return moment(a).format('M/DD/YYYY hh:mm:ss') === moment(b).format('M/DD/YYYY HH:mm:ss');
            } else if (type === 'epoch' || type === 'ms' || type === 'millisecond'){
                // compare epoch in Ms
                return moment(a).toDate().getTime() === moment(b).toDate().getTime();
            } else {
                return a == b;
            }
        } catch(ex){
            debug("util.isSameValue - ex=", ex);
            return false;
        }
    }

