    getNextNodeAfterSelection() {
        const selection = window.getSelection();

        // Check if there is a selection
        if (!selection.rangeCount) return null; // No selection made

        // Get the first range of the selection
        const range = selection.getRangeAt(0);

        // Get the end container from the range
        const endContainer = range.endContainer;

        // If the endContainer has a next sibling, return that
        if (endContainer.nextSibling) {
            return endContainer.nextSibling;
        }

        // If there is no next sibling, move up the DOM tree to find the next branching point
        let currentNode = endContainer;
        while (currentNode.parentNode) {
            currentNode = currentNode.parentNode;
            if (currentNode.nextSibling) {
                return currentNode.nextSibling;
            }
        }

        // If no next node is found in the document structure
        return null;
    }

    getPreviousNodeAfterSelection() {
        const selection = window.getSelection();

        // Check if there is a selection
        if (!selection.rangeCount) return null; // No selection made

        // Get the first range of the selection
        const range = selection.getRangeAt(0);

        // Get the end container from the range
        const endContainer = range.endContainer;

        // If the endContainer has a next sibling, return that
        if (endContainer.previousSibling) {
            return endContainer.previousSibling;
        }

        // If there is no next sibling, move up the DOM tree to find the next branching point
        let currentNode = endContainer;
        while (currentNode.parentNode) {
            currentNode = currentNode.parentNode;
            if (currentNode.previousSibling) {
                return currentNode.previousSibling;
            }
        }

        // If no next node is found in the document structure
        return null;
    }

    replaceSelectionWithHtml(html) {
        const selection = window.getSelection();
        if (selection.rangeCount > 0) {
            const range = selection.getRangeAt(0);
            range.deleteContents();

            // Create a temporary container for the HTML content
            const tempContainer = document.createElement('div');
            tempContainer.innerHTML = html;

            // Extract the nodes from the temporary container
            const fragment = document.createDocumentFragment();
            let node, lastNode;
            while ((node = tempContainer.firstChild)) {
                lastNode = fragment.appendChild(node);
            }

            // Insert the fragment at the range's position
            range.insertNode(fragment);

            // Adjust the selection to place the cursor after the inserted content
            if (lastNode) {
                range.setStartAfter(lastNode);
                range.setEndAfter(lastNode);
                selection.removeAllRanges();
                selection.addRange(range);
            }
        }
    }

