    callUntil(fn, interval, maxTime){
        if (interval > 0 && maxTime >= interval){
            let startTime = new Date().getTime();
            let timer = setInterval(() => {
                if (fn() || new Date().getTime() - startTime >= maxTime ){
                    clearInterval(timer);
                }
            }, interval);
        } else {
            throw "Invalid parameter";
        }

    }

