    // options: {dispatch, toast, callback}
    //		callback: (id, )
    acceptDropImages(e, options){
        let toast = options.toast;
        let dispatch = options.dispatch;
        let callback = options.callback;
        let ctx = options.ctx;

        var okCntr = 0, failCntr=0, totalCntr = e.dataTransfer.files.length;
        if ( e.dataTransfer.files.length > 0 ){
            // parse file name, size, type and content
            for(let file of e.dataTransfer.files){
                // only accept "images"
                if ( ['image/jpeg', 'image/png', 'image/jpg', 'image/gif'].indexOf(file.type.toLowerCase()) < 0 ){
                    failCntr++;
                    if (toast) toast.error(`1 file was rejected in uploading - (size: ${file.size}, type: ${file.type}).`);
                    continue;
                }

                var reader = new FileReader();
                reader.readAsDataURL(file);

                reader.onload = readerEvent => {
                    var content = readerEvent.target.result;
                    let _id = util.getJsonHash(content);

                    if (toast){
                        util.once('ImageAdded', () => {
                            toast.success(`1 file was accepted in uploading - (size: ${file.size}, type: ${file.type}).`);
                        });
                    }

                    ctx.imageMap.set(_id, {
                        srcInstance: ctx.instanceid,
                        name: file.name,
                        size: file.size,
                        type: file.type,
                        dataUrl: content,
                        createTime: new Date().getTime(),
                    });

                    /*
                    dispatch(util.actions.addImageFile({
                        _id,
                        name: file.name,
                        size: file.size,
                        type: file.type,
                        dataUrl: content,
                    }));
                    */

                    okCntr++;
                    if (callback) callback(_id, content);
                }
            }
        } else if ( e.dataTransfer.types.indexOf('text/plain') >= 0 && e.dataTransfer.types.indexOf('text/uri-list') >= 0 ){
            let url = util.getDataTransferLinks(e);
            util.prmsExtractContentFromUrl(  url ).then(res => {
                let _id = util.getJsonHash(res.base64data);

                if (toast){
                    util.once('ImageAdded', () => {
                        toast.success(`1 file was accepted in uploading - (size: ${res.size}, type: ${res.type}).`);
                    });
                }
                dispatch(util.actions.addImageFile({
                    _id,
                    size: res.size,
                    type: res.type,
                    dataUrl: res.base64data,
                }));

                if (callback) callback(_id, res.base64data);
            }).catch(err => {
                debugger
                if (toast) toast.error(`1 item was rejeected in uploading because of network error - (url: ${url}).`);
                // just add the url to image list
                /*
                let _id = util.getJsonHash(url);

                dispatch(util.actions.addImageUrl({
                    _id,
                    imgUrl: url
                }));

                if (toast) toast(`1 file was accepted in uploading - (url: ${url}).`);
                if (callback) callback(url);
                */
            })
        }
    }

    getDataTransferLinks(e){
        if ( e.dataTransfer.types.indexOf('text/plain') >= 0 && e.dataTransfer.types.indexOf('text/uri-list') >= 0 ){
            let text = e.dataTransfer.getData('text/plain');
            let link = e.dataTransfer.getData('text/uri-list');
            if (text == link){
                return link;
            }
        }
    }

