    // callback(data)
    onChannel(eventChannel, callback){
        util.on(eventChannel, callback);

        // pick up past events,
        // note: it's up to the subscriber to clear data after processing
        if ( util.getChannel(eventChannel) ){
            callback( util.getChannel(eventChannel) );
        }

        // return unsubscribe()
        let unsub = () => {
            util.offChannel(eventChannel, callback);
        };
        return unsub;
    }

    // = off(event, callback)
