import { util, createDebug} from './chatbridge';
const debug = createDebug("(miniAppApi/websocket.js)"), dbg = debug;

let websocket = null;
let onMessageCallback = null;

let forCompIndex = null;
export const getForCompIndex = () => forCompIndex;
export const setForCompIndex = index => {
    forCompIndex = index;

    for(let callback of forCompIndexListeners){
        try {
            callback();
        } catch(ex){
            debug("forCompIndex listener ex = ", ex);
        }
    }
}

let forCompIndexListeners = [];
export const onForCompIndexChange = (callback) => {
    forCompIndexListeners.push(callback);

    return () => {
        let pos = forCompIndexListeners.indexOf(callback);
        if (pos >= 0){
            forCompIndexListeners.splice(pos,1);
        }
    }
}

// Determine protocol (ws: or wss:) based on current page's protocol
// Uses VITE_... environment variables as overrides if available, otherwise defaults to window location.
const wsProtocol = /*import.meta.env.VITE_WEBSOCKET_PROTOCOL ||*/ (window.location.protocol === "https:" ? "wss:" : "ws:");

// Determine host (e.g., localhost:3000 or yourdomain.com) from current page's host
const wsHost = /*import.meta.env.VITE_WEBSOCKET_HOST ||*/ window.location.host;

// Construct the WebSocket URL relative to the origin.
// If your app is at https://yourdomain.com/miniApps/AccountBooks/,
// this will correctly point to wss://yourdomain.com/websocket
const WEBSOCKET_URL = `${wsProtocol}//${wsHost}/websocket`;

export const connectWebSocket = (onOpenCallback, onCloseCallback, onErrorCallback) => {
    if (websocket && websocket.readyState === WebSocket.OPEN) {
        debug("WebSocket is already connected.");
        if (onOpenCallback) onOpenCallback();       // Notify if already open
        return;
    }

    debug(`Attempting to connect to WebSocket at: ${WEBSOCKET_URL}`);
    websocket = new WebSocket(WEBSOCKET_URL);

    websocket.onopen = () => {
        debug("WebSocket connection established");
        if (onOpenCallback) onOpenCallback();
    };

    websocket.onmessage = (event) => {
        debug("WebSocket message received:", event.data);
        if (onMessageCallback) {
            try {
                // Attempt to parse if it's JSON, otherwise pass as string
                const parsedData = JSON.parse(event.data);
                onMessageCallback(parsedData);
            } catch (error) {
                onMessageCallback(event.data); // Pass raw data if not JSON
            }
        }
    };

    websocket.onerror = (error) => {
        debug("WebSocket error:", error);
        if (onErrorCallback) onErrorCallback(error);
    };

    websocket.onclose = (event) => {
        debug("WebSocket connection closed:", event.code, event.reason);
        websocket = null; // Clear the instance on close
        if (onCloseCallback) onCloseCallback(event);
    };
};

export const disconnectWebSocket = () => {
    setForCompIndex(null);      // another indicator

    if (websocket) {
        try {
            debug("Disconnecting WebSocket...");
            websocket.close();
        } catch(ex){
            debug("websocket close exception - ex=", ex);
        }
        // Note: The actual clearing of the `websocket` variable and `onCloseCallback`
        // firing will happen in the `websocket.onclose` event handler.
    } else {
        debug("No active WebSocket connection to disconnect.");
    }
};

export const sendMessage = (message) => {
    if (websocket && websocket.readyState === WebSocket.OPEN) {
        try {
            const messageString = typeof message === 'string' ? message : JSON.stringify(message);
            websocket.send(messageString);
            debug("WebSocket message sent:", messageString);
        } catch (error) {
            debug("Failed to send WebSocket message:", error);
        }
    } else {
        debug("WebSocket is not connected. Cannot send message.");
    }
};

export const setOnMessageCallback = (callback) => {
    onMessageCallback = callback;
};

export const getWebSocketState = () => {
    if (!websocket) return WebSocket.CLOSED; // Or a custom state like 'NOT_INITIALIZED'
    return websocket.readyState;
};

// Export readyState constants for convenience in components
export const WebSocketStates = {
    CONNECTING: WebSocket.CONNECTING, // 0
    OPEN: WebSocket.OPEN,             // 1
    CLOSING: WebSocket.CLOSING,       // 2
    CLOSED: WebSocket.CLOSED          // 3
};